   "id": "ze86d166a",
   "sez": "prima",
   "titolo": "Il Papa al Gemelli per un'operazione al polmone: udienze annullate fino al 20 ottobre",
   "orig": "Il Papa al Gemelli per l'operazione al polmone, annullate tutte le udienze fino al 20 ottobre",
   "lead": "Papa Leone è atteso al Policlinico Gemelli di Roma per sottoporsi a un intervento chirurgico al polmone, programmato a seguito della comparsa di un nodulo emerso durante controlli di routine. In Vaticano filtra ottimismo sulle sue condizioni e si riferisce che il pontefice è di buon umore. Tutte le udienze pubbliche sono state ufficialmente annullate fino al 20 ottobre per consentire l'operazione e il successivo decorso post-operatorio, mentre proseguono i preparativi per il viaggio in Sudamerica.",
   "more": [
    "Il Policlinico Universitario Agostino Gemelli è la storica struttura ospedaliera romana scelta tradizionalmente per i ricoveri e gli interventi chirurgici dei pontefici. I controlli diagnostici polmonari eseguiti periodicamente consentono di individuare tempestivamente eventuali anomalie o formazioni nodulari, facilitando interventi mirati a scopo terapeutico o preventivo prima che possano evolvere in complicazioni più severe."
   ],
