   "id": "zb1556f8e",
   "sez": "organizzazioni",
   "titolo": "L'Unione europea fissa la posizione negoziale per i vertici su clima e biodiversità",
   "orig": "Multilateralism: Council sets EU position ahead of climate change and biodiversity summits",
   "lead": "Il Consiglio dell'Unione europea ha approvato le conclusioni formali che stabiliscono la posizione negoziale comune dei Ventisette in vista dei prossimi vertici internazionali delle Nazioni Unite. L'intesa fissa le priorità strategiche dell'Unione per la conferenza sul clima COP31 e per il vertice globale sulla biodiversità COP17. I rappresentanti degli Stati membri hanno ribadito l'impegno dell'Europa a sostegno del multilateralismo e della cooperazione internazionale per raggiungere gli obiettivi concordati sulla riduzione delle emissioni serra e sulla tutela degli ecosistemi naturali nel mondo. Lo riferisce il Consiglio dell'Unione europea.",
   "more": [
    "I consigli dei ministri dell'Unione europea definiscono le linee guida vincolanti che i delegati comunitari devono sostenere durante i vertici promossi dalle Nazioni Unite. Queste conclusioni delineano gli impegni finanziari, i target di riduzione dell'inquinamento e i meccanismi di verifica per la salvaguardia delle specie, assicurando che l'Unione si presenti ai negoziati con un'unica voce politica."
   ],
