   "id": "z582f5fb1",
   "sez": "salute",
   "titolo": "Modificare la camminata riduce il dolore da artrosi al ginocchio senza farmaci",
   "orig": "New Way to Relieve Arthritic Knees Without Drugs or Surgery by Changing Your Gait",
   "lead": "Uno studio clinico della durata di un anno evidenzia come una semplice modifica nel modo di camminare possa alleviare il dolore provocato dall'artrosi al ginocchio in misura paragonabile ai trattamenti farmacologici, senza richiedere interventi chirurgici o pillole. La ricerca ha rilevato che correggere l'angolo di appoggio del piede durante la camminata riduce le sofferenze articolari e rallenta il deterioramento della cartilagine, riscontrato anche attraverso risonanze magnetiche. Il disturbo colpisce quasi un quarto degli individui sopra i quarant'anni, per i quali non esistono attualmente terapie capaci di invertire il danno cartilagineo.",
   "more": [
    "L'osteoartrosi al ginocchio è una malattia cronica degenerativa caratterizzata dalla graduale usura della cartilagine articolare, il tessuto che ammortizza i carichi tra le ossa della gamba. Quando questa protezione naturale si assottiglia, il movimento produce attrito, infiammazione e dolore, limitando severamente la mobilità quotidiana di milioni di pazienti."
   ],
