   "orig": "Multe a Roma, il Campidoglio ha incassato 154 milioni dalle famiglie: è tra le prime città in Italia",
   "lead": "Il Comune di Roma ha registrato entrate per centocinquantaquattro milioni di euro derivanti dalle sanzioni stradali pagate dai cittadini, collocandosi ai vertici della graduatoria tra le grandi città in Italia. La voce delle contravvenzioni si affianca all'imposta sul reddito, alle addizionali e ai tributi comunali ordinari, andando ad aggravare la pressione economica complessiva che incide sui bilanci familiari della capitale, dove le sanzioni per infrazioni al codice della strada rappresentano una componente rilevante delle entrate dell'amministrazione capitolina. Lo riferisce Il Messaggero – Roma.",
