   "titolo": "Zelensky accusa Mosca di violare la tregua energetica, il Cremlino prende tempo",
   "orig": "Zelensky Accuses Russia of Breaking Energy Ceasefire as Kremlin Says Talks Ongoing",
   "lead": "Il presidente ucraino Volodymyr Zelensky ha denunciato nuovi bombardamenti russi contro le infrastrutture energetiche dell'Ucraina, accusando la Russia di avere infranto l'intesa per un cessate il fuoco mirato alle reti elettriche. Da Mosca, il portavoce del Cremlino Dmitry Peskov non ha confermato l'adesione formale a una tregua specifica promossa su impulso statunitense, limitandosi a dichiarare che i contatti diplomatici rimangono in corso. Kyiv lamenta il proseguimento degli attacchi agli impianti strategici mentre la popolazione affronta i rischi dell'interruzione di forniture critiche in vista dell'inverno.",
   "more": [
    "Le infrastrutture energetiche costituiscono da mesi uno dei bersagli principali nel conflitto tra Russia e Ucraina. I bombardamenti sistematici su centrali e sottostazioni elettriche provocano blackout diffusi e blocchi nel riscaldamento urbano, spingendo la diplomazia a tentare tregue settoriali per proteggere le reti civili."
   ],
