   "id": "z9ff50d43",
   "sez": "musica",
   "titolo": "Troye Sivan pubblica l'album She's the Best tra sonorità pop e introspezione",
   "orig": "On 'She's the Best,' Troye Sivan takes the party to unexpected places",
   "lead": "Il cantautore australiano Troye Sivan ha pubblicato il suo nuovo progetto discografico intitolato She's the Best, un lavoro che approfondisce i suoi desideri personali ed esplora percorsi sonori inediti. La nuova uscita arriva dopo un periodo di grandi riconoscimenti per l'artista, segnato dalle sue prime nomination ai Grammy, da un tour mondiale congiunto insieme a Charli xcx e da un'ampia visibilità mediatica. Il disco mescola influenze stilistiche differenti, spaziando dal pop d'autore a richiami shoegaze, sonorità baleariche e rimandi alla tradizione degli Smiths.",
   "more": [
    "Troye Sivan è un cantante e autore australiano affermatosi a livello globale con un synth-pop raffinato e intimo. Nel corso della sua carriera ha saputo costruire un forte seguito internazionale nel pop alternativo, distinguendosi per testi personali e collaborazioni di rilievo con esponenti della scena musicale contemporanea."
   ],
