   "id": "za45f3597",
   "sez": "sport",
   "titolo": "L'European Tour chiude le porte ai golfisti della lega rivale LIV Golf",
   "orig": "European Tour gives LIV golfers ultimatum and shuts door on playing both",
   "lead": "La dirigenza dell'European Tour ha comunicato un fermo aut aut ai giocatori professionisti, sancendo l'impossibilità di competere nei propri tornei ufficiali per chiunque decida di prendere parte al circuito della LIV Golf. La decisione chiude ogni spiraglio alla possibilità di alternarsi tra le due manifestazioni, stabilendo che a partire dal 2027 il DP World Tour rifiuterà l'iscrizione a quanti abbiano sottoscritto accordi con la lega sostenuta dai fondi sauditi, inasprendo la frattura istituzionale in corso nel mondo del golf professionistico.",
   "more": [
    "La LIV Golf è una lega professionistica nata in concorrenza con i circuiti tradizionali del PGA Tour e dell'European Tour, offrendo ingenti montepremi che hanno attirato numerosi campioni mondiali. Questo scontro ha provocato squalifiche, contenziosi legali e dispute sulla partecipazione alle competizioni per nazioni come la Ryder Cup."
   ],
