   "id": "z9f537df5",
   "sez": "musica",
   "titolo": "James Hetfield esclude la politica dai concerti dei Metallica a Las Vegas",
   "orig": "James Hetfield: «I Metallica non sono qui per influenzarvi con le loro stronz@te»",
   "lead": "Il frontman dei Metallica James Hetfield ha chiarito la linea della band rock in merito alla presenza di messaggi ideologici sul palco, dichiarando apertamente che il gruppo non intende proporre discorsi politici durante le proprie esibizioni allo Sphere di Las Vegas. Il musicista ha ribadito con toni decisi che il pubblico partecipa ai concerti per ascoltare musica senza dover subire agende o prediche da parte degli intrattenitori, definendo il ruolo del palco come uno spazio dedicato esclusivamente alla dimensione artistica e all'intrattenimento dal vivo.",
   "more": [
    "I Metallica sono una delle formazioni heavy metal più celebri della storia, attiva dai primi anni Ottanta. Lo Sphere di Las Vegas è un'innovativa struttura per spettacoli caratterizzata da schermi LED immersivi ad altissima risoluzione, progettata per offrire esperienze visive e sonore all'avanguardia."
   ],
