   "id": "z425826d2",
   "sez": "cucina",
   "titolo": "Leonia degli Albizzi e la prima cantina gravitazionale per il Metodo Classico",
   "orig": "Fu una donna a sperimentare in Toscana il Metodo Classico e a progettare la prima cantina gravitazionale italiana",
   "lead": "Nel corso dell'Ottocento, Leonia degli Albizzi, moglie di Angiolo Frescobaldi, intuì la vocazione spumantistica del territorio dell'Appennino toscano, diventando una figura pionieristica nella sperimentazione del Metodo Classico nella regione. Oltre alle innovazioni enologiche nella produzione di bollicine, la nobildonna progettò la prima cantina italiana concepita per sfruttare la forza di gravità nei processi di vinificazione, riducendo le sollecitazioni meccaniche sulle uve. Il suo lavoro ha anticipato concetti architettonici e pratiche di lavorazione ampiamente valorizzati nella viticoltura contemporanea di qualità.",
   "more": [
    "Il Metodo Classico è un procedimento di produzione di vini spumanti che prevede una seconda fermentazione direttamente all'interno della bottiglia. La vinificazione per gravità sfrutta dislivelli naturali nella struttura dell'edificio per spostare mosto e vino senza l'uso di pompe, preservando l'integrità del prodotto."
   ],
