   "titolo": "L'arco narrativo futuro del manga Phoenix di Tezuka debutta a teatro a Tokyo",
   "orig": "Osamu Tezuka's Phoenix Manga's Future Arc Gets Stage Play in February",
   "lead": "L'arco narrativo Mirai-hen del celebre manga Phoenix, capolavoro del maestro Osamu Tezuka, sarà trasposto in un adattamento teatrale intitolato Hi no Tori Mirai-hen ZEROMDISTANCE. Lo spettacolo andrà in scena sul palcoscenico a Tokyo nei primi giorni di febbraio, offrendo agli appassionati una rilettura drammaturgica di una delle saghe più influenti della storia del fumetto nipponico. L'annuncio si inserisce in una stagione ricca di trasposizioni per le grandi opere giapponesi, tra spettacoli dal vivo e nuovi progetti animati.",
   "more": [
    "Phoenix, noto in originale come Hi no Tori, è una delle creazioni più ambiziose di Osamu Tezuka, incentrata sulla ricerca dell'immortalità attraverso epoche storiche diverse, dal passato remoto al futuro distopico. L'opera è considerata una pietra miliare del fumetto d'autore per profondità filosofica e innovazione visiva."
   ],
