   "titolo": "La Marina francese intercetta nell'Oceano Indiano una petroliera ombra russa",
   "orig": "French Navy intercepts Russian shadow fleet tanker in Indian Ocean",
   "lead": "Le forze navali della Marina militare francese hanno intercettato nelle acque dell'Oceano Indiano la nave cisterna DF Peak, imbarcazione riconducibile alla cosiddetta flotta ombra russa precedentemente registrata con il nome di Kaliningrad. La petroliera viaggiava esponendo in modo fraudolento la bandiera del Benin ed era già stata inserita negli elenchi delle sanzioni internazionali da parte di Stati Uniti, Unione Europea, Svizzera, Canada e Giappone per elusione delle restrizioni sulle esportazioni petrolifere di Mosca. Lo riferisce The Kyiv Independent.",
