   "sez": "spazio",
   "titolo": "Rilevato un lampo radio veloce da record generato nell'universo primordiale",
   "orig": "Lampi radio veloci: record di distanza",
   "lead": "Un gruppo di astronomi ha individuato un lampo radio veloce che ha infranto ogni precedente primato di distanza percorsa nel cosmo. Il segnale radio proviene dall'universo primordiale, essendosi originato in un'epoca remotissima in cui il Sole non si era ancora formato. Per raggiungere i radiotelescopi sulla Terra, l'impulso ha attraversato circa l'ottanta per cento dell'intera storia cosmica, aprendo preziose opportunità per misurare la distribuzione della materia intergalattica e comprendere i fenomeni estremi che caratterizzavano le prime fasi evolutive delle galassie.",
   "more": [
    "I fast radio burst sono impulsi energetici brevissimi, della durata di pochi millisecondi, che rilasciano una quantità enorme di onde radio. La loro origine rimane uno dei grandi enigmi dell'astrofisica, spesso associata a corpi celesti ad altissima densità come le stelle di neutroni dotate di intensi campi magnetici."
   ],
