   "sez": "organizzazioni",
   "titolo": "Allargamento dell'Unione europea, chiusi tre capitoli negoziali con il Montenegro",
   "orig": "Enlargement: EU and Montenegro close accession negotiations in the areas of economic and monetary policy, statistics, and social policy and employment",
   "lead": "L'Unione europea e il Montenegro hanno concordato la chiusura provvisoria di tre importanti capitoli nei negoziati per l'adesione all'Unione, segnando un avanzamento tangibile nel percorso di integrazione comunitaria di Podgorica. Le intese raggiunte riguardano specificamente le materie di politica economica e monetaria disciplinate dal capitolo diciassette, il settore della statistica relativo al capitolo diciotto e le disposizioni sulla politica sociale e l'occupazione previste dal capitolo diciannove, a conferma dei progressi compiuti dal Paese balcanico nell'adeguamento normativo agli standard europei. Lo riferisce Consiglio dell'Unione europea.",
   "more": [
    "I negoziati di adesione all'Unione europea sono suddivisi in oltre trenta capitoli tematici che coprono l'intero quadro giuridico comunitario. La chiusura di ciascun capitolo certifica che il Paese candidato ha recepitio e dimostrato di poter applicare le normative comunitarie in quel determinato ambito."
   ],
