   "sez": "salute",
   "titolo": "Allarme antibiotico-resistenza: gli allevamenti ne consumano più della sanità umana",
   "orig": "AMR: Livestock uses more antibiotics than human health sector – Pate",
   "lead": "Il settore dell'allevamento animale impiega una quantità di medicinali antibatterici nettamente superiore rispetto a quella utilizzata nella sanità umana. A lanciare l'allarme è Muhammad Ali Pate, il quale ha sottolineato che la resistenza antimicrobica rappresenta una minaccia capace di trasferirsi rapidamente tra individui, fauna e ambiente circostante. Per contrastare l'evoluzione di agenti patogeni resistenti risulta perciò indispensabile favorire una stretta cooperazione integrata tra i differenti settori produttivi e sanitari. Lo riferisce Premium Times.",
   "more": [
    "L'antibiotico-resistenza è la capacità acquisita dai batteri di sopravvivere ai trattamenti farmacologici, un fenomeno accelerato dall'abuso di medicinali negli ospedali e negli allevamenti intensivi."
   ],
