   "id": "z5da351d8",
   "sez": "cultura",
   "titolo": "Tagikistan, Dushanbe conquista il Gran Premio per i risultati delle donne",
   "orig": "Dushanbe wins Grand Prix in Tajikistan’s national women’s achievement competition",
   "lead": "La capitale Dushanbe si è aggiudicata il prestigioso Gran Premio nell'ambito del concorso nazionale dedicato ai successi e ai traguardi raggiunti dalle donne in Tagikistan. Nel corso della cerimonia conclusiva dell'evento, le vincitrici e le delegazioni premiate hanno ricevuto diplomi ufficiali di riconoscimento, premi e doni commemorativi di pregio per celebrare il contributo femminile nello sviluppo civico e professionale del Paese centroasiatico.",
   "more": [
    "Il Tagikistan è una repubblica dell'Asia centrale indipendente dal 1991, la cui capitale Dushanbe costituisce il fulcro istituzionale e culturale delle politiche statali."
   ],
