   "lead": "Lo studio di architettura BIG ha svelato il progetto della Tirana Fountain Plaza, un edificio multifunzionale sospeso sopra il parco Rinia della capitale albanese. La struttura, concepita con forme simili a una nuvola e rivestita da dischi bianchi e facciate traslucide, poggerà su snelle colonne per mantenere il piano terra ampiamente accessibile come spazio pubblico. Il complesso integrerà residenze, uffici, aree dedicate alla cultura e giochi d'acqua inseriti in terrazze sovrapposte.",
