   "lead": "Cora Walsh, studentessa di scuola media di Long Island nello stato di New York, si è aggiudicata l'edizione 2026 della NPR Student Podcast Challenge grazie a una puntata autobiografica sul suo percorso personale con la dislessia. Nella sua trasmissione audio la ragazza racconta gli anni in cui detestava la lettura prima di giungere alla corretta diagnosi medica, spiegando come la comprensione delle proprie difficoltà abbia cambiato il suo approccio all'apprendimento. Lo riferisce NPR – Istruzione.",
