   "lead": "La cerimonia degli American Manga Awards 2026 si è affermata come uno dei principali appuntamenti dell'industria del manga negli Stati Uniti, riunendo autori, traduttori, addetti all'adattamento e lettori. La serata ha celebrato il talento artistico, le competenze tecniche e la dedizione che collegano i mercati su entrambe le sponde dell'oceano Pacifico, offrendo al contempo uno spazio di discussione per sollecitare miglioramenti e riforme all'interno del comparto editoriale. Lo riferisce Anime Herald.",
