   "lead": "Il piano d'azione invernale per la qualità dell'aria a Delhi subisce una battuta d'arresto a causa dello slittamento della consegna delle nuove spazzatrici meccaniche stradali, attese ora non prima di fine novembre. Il ministro dell'Ambiente locale, Manjinder Singh Sirsa, ha spiegato che è stato formalizzato un ordine per 70 macchine spazzatrici di grandi dimensioni, ma soltanto una parte della flotta riuscirà a giungere in servizio entro la fine del mese prossimo per pulire le carreggiate dalla polvere. Lo riferisce The Hindu.",
