   "titolo": "Matera, l'antica tradizione dei timbri del pane usati anche per chiedere la mano",
   "orig": "Una volta ogni famiglia aveva un timbro per riconoscere il proprio pane. E si regalava anche per chiedere la mano",
   "lead": "In passato nei forni comuni ogni famiglia incideva sulla propria pagnotta un contrassegno unico servendosi di un caratteristico timbro in legno, così da distinguere il pane fatto in casa durante la cottura collettiva. Nella città di Matera questo manufatto artigianale assumeva persino un profondo valore sociale, venendo donato come pegno e simbolo formale di fidanzamento quando un uomo chiedeva la mano della futura sposa prima delle nozze. Lo riferisce Gambero Rosso.",
