   "orig": "Hong Kong police launch AI-powered national security platform for school pupils",
   "lead": "La polizia di Hong Kong ha lanciato NSmarties, una piattaforma interattiva dotata di intelligenza artificiale pensata per insegnare i principi della sicurezza nazionale agli allievi delle scuole. Lo strumento è stato introdotto durante una cerimonia pubblica alla Precious Blood Primary School di Ap Lei Chau davanti a circa 700 studenti, alla presenza del commissario Joe Chow. L'iniziativa rientra nelle attività educative delle forze dell'ordine per spiegare il quadro normativo vigente attraverso sistemi digitali.",
