   "titolo": "Abitare sociale: Homes4All condivide il modello per rigenerare immobili vuoti",
   "orig": "Abitare sociale, Homes4All lancia un modello per rigenerare immobili inutilizzati e creare housing accessibile",
   "lead": "La società Homes4All ha promosso un modello operativo destinato a trasferire competenze tecniche a professionisti, imprese del settore e organizzazioni del terzo settore impegnate nell'abitare sociale. L'obiettivo primario è convertire edifici inutilizzati o degradati in alloggi accessibili e sostenibili, mettendo a disposizione soluzioni già sperimentate per contrastare l'emergenza abitativa urbana attraverso pratiche di riqualificazione strutturale degli spazi dismessi. Lo riferisce Il Sole 24 Ore – Casa24.",
   "more": [
    "L'housing sociale comprende progetti residenziali mirati a offrire alloggi a canoni contenuti a famiglie o individui con redditi medi o bassi."
   ],
