   "id": "z263dcd53",
   "sez": "manga",
   "titolo": "Conversazione con KAZÉ ad Anime NYC sul valore universale dei manga",
   "orig": "A Conversation with KAZÉ at Anime NYC 2026",
   "lead": "Durante l'evento Anime NYC 2026 a New York, Seth Burn ha tenuto una conversazione con KAZÉ incentrata sull'importanza della narrazione nei manga. Nel corso del dialogo è stato sottolineato come il fumetto giapponese rappresenti una forma d'arte fortemente legata alla prospettiva e alle esperienze vissute dai singoli autori, capace tuttavia di creare un legame profondo con il pubblico degli Stati Uniti. Questa forma espressiva dimostra che, indipendentemente dalla società di provenienza, dal luogo di residenza o dal contesto di crescita, la narrazione consente sempre di stabilire autentiche connessioni umane. Lo riferisce Anime Herald.",
   "more": [
    "Anime NYC è una delle principali fiere dedicate alla cultura pop e all'animazione giapponese negli Stati Uniti. La manifestazione richiama ogni anno editori, autori e appassionati per celebrare l'influenza globale dei manga, evidenziando il ruolo delle opere a fumetti nipponiche come mezzo di scambio culturale e artistico a livello internazionale."
   ],
