   "id": "zb45a44cf",
   "sez": "ambiente",
   "titolo": "Inaugurato un nuovo sentiero boschivo vicino al Parco di Muránska Planina in Slovacchia",
   "orig": "New forest trail opens near Slovakia’s ground squirrel meadow",
   "lead": "In Slovacchia è stato inaugurato un nuovo sentiero naturalistico nel bosco situato nelle vicinanze del prato dei citelli e del Parco nazionale Muránska Planina. Il percorso pedonale, della durata stimata di circa un'ora, attraversa una zona boschiva ed è dotato di diverse tappe informative pensate per illustrare ai visitatori le caratteristiche della vegetazione locale, l'ecosistema forestale e le specie della fauna selvatica che popolano l'area protetta. L'iniziativa punta a valorizzare il patrimonio ambientale del territorio offrendo un'esperienza didattica immersa nella natura. Lo riferisce The Slovak Spectator.",
   "more": [
    "Il Parco nazionale Muránska Planina è un'area naturale protetta della Slovacchia centrale nota per la sua biodiversità, i rilievi carsici e la presenza di ampie praterie dove vivono colonie di citelli. Questi piccoli roditori rappresentano un elemento caratteristico dell'ecosistema locale e una delle principali attrazioni naturalistiche della regione."
   ],
