   "sez": "organizzazioni",
   "titolo": "L'Aiea pubblica il trecentosettantesimo aggiornamento sulla sicurezza nucleare in Ucraina",
   "orig": "Update 370 – IAEA Director General Statement on Situation in Ukraine",
   "lead": "L'Agenzia internazionale per l'energia atomica ha pubblicato a Vienna il trecentosettantesimo aggiornamento ufficiale con la dichiarazione del direttore generale sull'evoluzione della situazione in Ucraina. La comunicazione dell'organismo internazionale riferisce sullo stato della sicurezza nucleare nel Paese esteuropeo, proseguendo l'attività di monitoraggio costante delle condizioni degli impianti nucleari e dei potenziali rischi legati al conflitto. Il nuovo bollettino informativo fornisce un resoconto puntuale sull'integrità operativa delle infrastrutture energetiche atomiche ucraine e sulle valutazioni tecniche dell'ente di vigilanza delle Nazioni Unite. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "L'Agenzia internazionale per l'energia atomica è l'organizzazione intergovernativa che promuove l'uso pacifico dell'energia nucleare e vigila sugli standard di sicurezza degli impianti nel mondo. In Ucraina l'agenzia mantiene esperti sul campo per supervisionare le centrali e prevenire incidenti radiologici in contesti bellici."
   ],
