   "id": "z3abfadb9",
   "sez": "tech",
   "titolo": "Raid ucraini sui server Yandex in Russia: calano fake news e bot della propaganda",
   "orig": "Colpiti data center russi, dati anomali anche in Italia: presto per parlare di stop alla propaganda",
   "lead": "In seguito agli attacchi con droni condotti dall'Ucraina contro i server e i data center russi di Yandex, le analisi dei flussi online hanno evidenziato anomalie nei dati e un crollo di post virali e fake news, con effetti rilevati anche in Italia. Gli apparati di sicurezza mantengono sotto osservazione l'impatto sui bot della propaganda filorussa, mentre proseguono le indagini sui sistemi di pagamento impiegati da chi diffonde disinformazione sul web. Gli esperti ritengono tuttavia prematuro considerare definitivamente interrotta la macchina propagandistica di Mosca, nonostante il temporaneo inceppamento delle reti digitali.",
   "more": [
    "I data center sono infrastrutture informatiche che ospitano server dedicati alla gestione e all'elaborazione di enormi volumi di dati su scala globale. Yandex rappresenta il principale motore di ricerca e fornitore di servizi digitali in Russia, svolgendo un ruolo centrale nella circolazione delle informazioni e nei canali di comunicazione online del Paese."
   ],
