   "id": "z45441f4b",
   "sez": "ingegneria",
   "titolo": "Consorzio internazionale si aggiudica il maxi appalto per i trasporti in Repubblica Ceca",
   "orig": "Ferrovial and Strabag team win Czech Republic’s largest transport PPP contract",
   "lead": "Un consorzio composto dall'investitore Invesis, dall'austriaca Strabag, dalla polacca Budimex e dalla spagnola Cintra, entrambe controllate di Ferrovial, ha siglato un contratto di partenariato pubblico-privato della durata di ventotto anni con il ministero dei Trasporti della Repubblica Ceca. L'accordo costituisce la maggiore intesa infrastrutturale di questo tipo mai conclusa nel Paese per il potenziamento dei trasporti. Nel frattempo, sul territorio ceco si avvicinano le celebrazioni per la festa nazionale del 28 ottobre, data in cui la legge impone la chiusura della maggioranza dei grandi supermercati e delle catene commerciali con superficie superiore a duecento metri quadrati.",
   "more": [
    "Il partenariato pubblico-privato è una formula contrattuale che consente alle amministrazioni pubbliche di realizzare e gestire grandi opere infrastrutturali collaborando con aziende private. Queste ultime si occupano della progettazione, del finanziamento e della manutenzione a lungo termine delle reti di trasporto in cambio di canoni periodici o concessioni operative."
   ],
