   "id": "z7a698bbb",
   "sez": "sport",
   "titolo": "Atletica di Hong Kong a secco di medaglie ai Giochi Asiatici di Aichi-Nagoya",
   "orig": "Hong Kong athletics team face make-or-break period after 0 medals at Asian Games",
   "lead": "La squadra di atletica di Hong Kong affronta una fase decisiva dopo aver concluso senza alcuna medaglia la partecipazione ai Giochi Asiatici di Aichi-Nagoya. Nonostante il bilancio complessivo della delegazione sia stato storico, con undici ori e cinquantaquattro medaglie totali ottenute in quattordici discipline tra cui vela, scherma, nuoto, ciclismo, karate e squash, la pista non ha portato podi. Negli stessi Giochi, atleti cinesi come Zhang Yuetong hanno tracciato un bilancio positivo delle medaglie conquistate guardando ai futuri obiettivi olimpici di Los Angeles 2028.",
   "more": [
    "I Giochi Asiatici costituiscono la più importante manifestazione multisportiva del continente asiatico, organizzata a cadenza quadriennale sotto l'egida del Consiglio Olimpico d'Asia. L'evento riunisce atleti provenienti da decine di federazioni nazionali e rappresenta un fondamentale banco di prova per misurare la competitività in vista dei Giochi Olimpici."
   ],
