   "titolo": "Grave siccità a New Ireland: mobilitati aiuti alimentari e idrici per la popolazione",
   "orig": "New Ireland Administration deploys Food and Water Aid amid prolonged Drought",
   "lead": "L'amministrazione provinciale di New Ireland, in Papua Nuova Guinea, è entrata in piena modalità di risposta ai disastri stanziando un piano di aiuti da svariati milioni di kina per fronteggiare una grave e prolungata siccità. L'intervento di emergenza prevede la distribuzione straordinaria di generi alimentari e scorte di acqua potabile a favore delle comunità locali colpite dalle estreme condizioni climatiche che interessano l'intero territorio provinciale. Le autorità hanno mobilitato risorse finanziarie per sostenere la popolazione messa a dura prova dalla scarsità idrica. Lo riferisce Post-Courier.",
   "more": [
    "La provincia di New Ireland è un territorio insulare della Papua Nuova Guinea dipendente dalle precipitazioni regolari per l'agricoltura di sussistenza e l'approvvigionamento idrico. Periodi prolungati di aridità provocano gravi ripercussioni sulle coltivazioni tradizionali e mettono a rischio la sicurezza idrica dei villaggi isolati."
   ],
