   "sez": "spazio",
   "titolo": "Il Nobel per la Fisica 2026 a Francis Halzen per l'astronomia dei neutrini",
   "orig": "Neutrino Hunter Francis Halzen Wins Nobel Prize in Physics",
   "lead": "Il fisico delle particelle Francis Halzen è stato insignito del premio Nobel per la Fisica 2026 per i suoi contributi determinanti all'astronomia dei neutrini e all'osservatorio IceCube in Antartide. Halzen, scienziato belga naturalizzato statunitense, ha reso possibile la rilevazione di neutrini ad altissima energia di origine astrofisica aprendo una nuova finestra di osservazione sul cosmo. La comunità scientifica internazionale sottolinea come questo riconoscimento evidenzi anche il ruolo strategico dell'ambiente estremo antartico, utilizzato da oltre un secolo dai ricercatori come piattaforma privilegiata per esplorare l'universo.",
   "more": [
    "I neutrini sono particelle elementari prive di carica elettrica e con massa quasi nulla, capaci di viaggiare attraverso lo spazio per miliardi di anni luce senza essere deviate o assorbite dalla materia. L'osservatorio IceCube sfrutta i ghiacci perenni dell'Antartide per individuare le rarissime collisioni di queste particelle provenienti da fenomeni cosmici estremi."
   ],
