   "sez": "salute",
   "titolo": "Sudafrica, la stretta sui prodotti naturali minaccia un settore da 22 miliardi di rand",
   "orig": "South Africa’s supplement crackdown risks R22bn health industry",
   "lead": "L'iniziativa del governo sudafricano volta a regolamentare i prodotti naturali per la salute e il benessere all'interno di un rigido regime farmaceutico rischia di mettere in crisi un comparto industriale dal valore di ventidue miliardi di rand. L'annunciata stretta normativa minaccia migliaia di posti di lavoro, la sopravvivenza di numerose piccole imprese e l'accessibilità economica degli integratori per i consumatori in Sudafrica. Gli operatori del settore del benessere temono che requisiti troppo severi possano soffocare le attività locali. Lo riferisce Mail & Guardian.",
   "more": [
    "Il mercato degli integratori alimentari e delle medicine tradizionali naturali comprende vitamine, erbe e prodotti fitoterapici ampiamente utilizzati per la prevenzione e il benessere. L'applicazione di standard normativi tipici dei medicinali con obbligo di prescrizione comporta complessi iter di registrazione che spesso gravano sui piccoli produttori."
   ],
