   "sez": "cultura",
   "titolo": "Giappone, nel 2026 si celebrano i cento anni dalla nascita dello scrittore Hoshi Shin’ichi",
   "orig": "Hoshi Shin’ichi: Japan’s Timeless Master of the Short-Short Story",
   "lead": "In occasione del centenario della nascita nel 2026, il Giappone celebra Hoshi Shin’ichi, celebre maestro dei racconti brevissimi e tra gli autori più amati del Paese da oltre mezzo secolo. Lo scrittore è ricordato a livello internazionale per la sua inesauribile vena creativa, che lo ha portato a comporre oltre mille storie brevi caratterizzate da trame fantascientifiche, acute riflessioni etiche e finali a sorpresa. L'anniversario rappresenta un'opportunità per riscoprire l'opera letteraria di un pioniere della narrativa d'immaginazione nipponica. Lo riferisce Nippon.com.",
   "more": [
    "Hoshi Shin’ichi è considerato uno dei padri della moderna fantascienza giapponese. Il formato del racconto brevissimo da lui perfezionato condensa narrazioni surreali e allegorie tecnologiche in pochissime pagine, influenzando intere generazioni di romanzieri, sceneggiatori di anime e autori di manga in Giappone."
   ],
